export function requireCurrentFootprintForwardWriterMainBootstraps(
  forward: CurrentFootprintForwardHeadBootstrap, selectedSql: CurrentSelectedFileMainSqlFenceBootstrap, transport: object,
): void {
  const head = forwardHeadBootstraps.get(forward);
  const selected = selectedSqlFenceBootstraps.get(selectedSql);
  if (head === undefined || selected === undefined || head.owner !== selected.owner ||
    head.transport !== transport || selected.transport !== transport || head.runner() !== selected.runner() ||
    forwardHeadOwnerBootstraps.get(head.owner) !== forward || selected.path !== head.source.rawWindowsPath ||
    !footprintForwardWriterCompleteFactories.has(head.owner)) {
    throw error("FORWARD_WRITER_MAIN_BOOTSTRAP_PAIR");
  }
  assertOriginalCurrentFootprintForwardWriterCompleteNativeOwner(head.owner);
}

