function inverseFullEffectNeedsColdSuccessor(request: RecordValue): boolean {
  const { action, method, phase } = request;
  return action === "footprint-inverse-native-delete-execution" && method === "Runtime.callFunctionOn" && phase === "inverse-native-delete-sender-invoke" ||
    action === "footprint-inverse-native-delete-execution-forward" && method === "Debugger.resume" && phase === "inverse-native-delete-execution-forward-resume" ||
    action === "footprint-inverse-native-delete-flow" && method === "Debugger.resume" && phase === "local//inverse-native-delete-local-resume/localIngress/";
}

async function reproveNativeDeleteColdAdmission(allocation: FootprintInverseFullAllocation): Promise<NativeDeleteColdAdmission> {
  requireFootprintInverseV4Preparation(allocation);
  const admitted = allocation.coldAdmission;
  if (admitted === null) { throw error("INVERSE_NATIVE_DELETE_COLD_ORIGINAL_ADMISSION"); }
  const pin = { bytes: admitted.options.powershellBytes, sha256: admitted.options.powershellSha256 };
  await verifyCurrentPcbDiagnosticPowerShell(admitted.powershellExecutable, pin);
  await admitted.helper.verify();
  requireFootprintInverseV4Preparation(allocation);
  const { options } = allocation;
  if (allocation.coldAdmission !== admitted || options.pluginRoot !== admitted.options.pluginRoot ||
      options.assetsRoot !== admitted.options.assetsRoot || options.wslDistribution !== admitted.options.wslDistribution ||
      options.powershellBytes !== pin.bytes || options.powershellSha256 !== pin.sha256) { throw error("INVERSE_NATIVE_DELETE_COLD_TRANSPORT_CHANGED"); }
  return admitted;
}

