/** Inspect only the original retained bootstrap registry; labels cannot select the V4 Main reader. */
export function isOriginalCurrentFootprintInverseV4MainSqlFenceBootstrap(capability:CurrentSelectedFileMainSqlFenceBootstrap,runner:CurrentFootprintCopyMainBackendRunner):boolean{
 const original=selectedSqlFenceBootstraps.get(capability);if(original===undefined){return false;}
 const factory=footprintInverseV4Factories.get(original.owner);if(factory===undefined){return false;}
 if(original.runner()!==runner){throw error("FOOTPRINT_INVERSE_V4_MAIN_ORIGINAL_RUNNER");}
 assertOriginalCurrentFootprintInverseV4NativeOwner(original.owner);original.reprove();requireFootprintInverseV4Preparation(factory.allocation);
 if(selectedSqlFenceBootstraps.get(capability)!==original||footprintInverseV4Factories.get(original.owner)!==factory||factory.allocation.owner!==original.owner||original.runner()!==runner){throw error("FOOTPRINT_INVERSE_V4_MAIN_BOOTSTRAP_CHANGED");}
 return true;
}


